// SPDX-License-Identifier: Apache-2.0
// hip_cpp seed for FlashInfer-Bench/025_rmsnorm_h4096.
//
// Exists to prove the ROCm C++ path end to end -- the packager compiling a
// .hip source with --offload-arch=gfx950, binding it through torch, and the
// result passing the AMD-derived tolerance -- NOT to be fast. It is a
// wavefront-per-row reduction with no tiling and no vectorization, and it is
// expected to score BELOW the PyTorch anchor.
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>
// getCurrentHIPStream lives here, not in HIPContext.h.
#include <c10/hip/HIPStream.h>

namespace {

constexpr int kHidden = 4096;
constexpr int kBlock = 256;          // threads per row

__global__ void rmsnorm_kernel(const __hip_bfloat16* __restrict__ x,
                               const __hip_bfloat16* __restrict__ w,
                               __hip_bfloat16* __restrict__ y,
                               int hidden, float eps) {
  const int row = blockIdx.x;
  const int tid = threadIdx.x;
  const __hip_bfloat16* xr = x + static_cast<long long>(row) * hidden;
  __hip_bfloat16* yr = y + static_cast<long long>(row) * hidden;

  float acc = 0.f;
  for (int i = tid; i < hidden; i += kBlock) {
    const float v = __bfloat162float(xr[i]);
    acc += v * v;
  }

  __shared__ float partial[kBlock];
  partial[tid] = acc;
  __syncthreads();
  for (int s = kBlock / 2; s > 0; s >>= 1) {
    if (tid < s) partial[tid] += partial[tid + s];
    __syncthreads();
  }

  // rsqrt of the MEAN of squares, matching the reference exactly: a kernel
  // that reduces the sum instead is off by sqrt(hidden) and would be caught
  // by the tolerance rather than by the compiler.
  const float inv_rms = rsqrtf(partial[0] / static_cast<float>(hidden) + eps);
  for (int i = tid; i < hidden; i += kBlock) {
    const float v = __bfloat162float(xr[i]) * inv_rms * __bfloat162float(w[i]);
    yr[i] = __float2bfloat16(v);
  }
}

}  // namespace

torch::Tensor run(const torch::Tensor& hidden_states,
                  const torch::Tensor& weight) {
  TORCH_CHECK(hidden_states.dim() == 2, "hidden_states must be 2D");
  TORCH_CHECK(hidden_states.size(1) == kHidden, "hidden_size must be 4096");
  TORCH_CHECK(hidden_states.scalar_type() == torch::kBFloat16, "bf16 only");
  TORCH_CHECK(weight.scalar_type() == torch::kBFloat16, "bf16 only");
  auto x = hidden_states.contiguous();
  auto w = weight.contiguous();
  auto y = torch::empty_like(x);

  const int rows = static_cast<int>(x.size(0));
  hipLaunchKernelGGL(rmsnorm_kernel, dim3(rows), dim3(kBlock), 0,
                     c10::hip::getCurrentHIPStream(),
                     reinterpret_cast<const __hip_bfloat16*>(x.data_ptr()),
                     reinterpret_cast<const __hip_bfloat16*>(w.data_ptr()),
                     reinterpret_cast<__hip_bfloat16*>(y.data_ptr()),
                     kHidden, 1e-5f);
  return y;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("run", &run, "RMSNorm h4096, bf16, gfx950 (hip_cpp seed)");
}
